#!/usr/bin/env node

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const workspace = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const sqliteSchemaPath = path.join(workspace, "prisma", "schema.prisma");
const postgresSchemaPath = path.join(workspace, "prisma", "postgresql", "schema.prisma");
const GENERATED_HEADER = [
  "// GENERATED by scripts/postgres/schema-contract.mjs from prisma/schema.prisma.",
  "// Do not edit this file directly; update the canonical SQLite schema and regenerate.",
  ""
].join("\n");

function sha256(value) {
  return createHash("sha256").update(value).digest("hex").toUpperCase();
}

export function renderPostgresSchema(sqliteSchema) {
  const datasource = /datasource\s+db\s*\{[\s\S]*?\n\}/;
  const block = sqliteSchema.match(datasource)?.[0];
  if (!block) throw new Error("POSTGRES_SCHEMA_DATASOURCE_MISSING");
  if (!/^\s*provider\s*=\s*"sqlite"\s*$/m.test(block)) {
    throw new Error("POSTGRES_SCHEMA_CANONICAL_PROVIDER_NOT_SQLITE");
  }
  if (!/^\s*url\s*=\s*env\("DATABASE_URL"\)\s*$/m.test(block)) {
    throw new Error("POSTGRES_SCHEMA_DATABASE_URL_CONTRACT_MISSING");
  }
  const postgresBlock = block
    .replace(/(^\s*provider\s*=\s*)"sqlite"(\s*$)/m, "$1\"postgresql\"$2")
    .replace(/(^\s*url\s*=\s*env\("DATABASE_URL"\)\s*$)/m, "$1\n  directUrl = env(\"DIRECT_URL\")");
  return `${GENERATED_HEADER}${sqliteSchema.replace(datasource, postgresBlock).replace(/^\uFEFF/, "")}`;
}

export function schemaContract() {
  const sqliteSchema = readFileSync(sqliteSchemaPath, "utf8").replaceAll("\r\n", "\n");
  const postgresSchema = renderPostgresSchema(sqliteSchema);
  return {
    sqliteSchema,
    postgresSchema,
    sqliteSha256: sha256(sqliteSchema),
    postgresSha256: sha256(postgresSchema)
  };
}

function main() {
  const mode = process.argv[2] ?? "--check";
  const contract = schemaContract();
  if (mode === "--write") {
    mkdirSync(path.dirname(postgresSchemaPath), { recursive: true });
    writeFileSync(postgresSchemaPath, contract.postgresSchema, "utf8");
  } else if (mode === "--check") {
    let committed = "";
    try {
      committed = readFileSync(postgresSchemaPath, "utf8").replaceAll("\r\n", "\n");
    } catch {
      throw new Error("POSTGRES_SCHEMA_NOT_GENERATED");
    }
    if (committed !== contract.postgresSchema) throw new Error("POSTGRES_SCHEMA_DRIFT");
  } else {
    throw new Error(`POSTGRES_SCHEMA_MODE_INVALID:${mode}`);
  }
  console.log(JSON.stringify({
    result: mode === "--write" ? "POSTGRES_SCHEMA_GENERATED" : "POSTGRES_SCHEMA_IN_SYNC",
    sqliteSha256: contract.sqliteSha256,
    postgresSha256: contract.postgresSha256
  }));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    main();
  } catch (error) {
    console.error(error instanceof Error ? error.message : "POSTGRES_SCHEMA_CONTRACT_FAILED");
    process.exitCode = 1;
  }
}
